def(491, 'Plaga drow', 'drow', 'poco', { cost: c(0, 4), text: 'Veneno 3 y le metés Pánico al rival', plusText: 'Veneno 5 y le metés Pánico al rival', camp: { after: (x) => { x.venom(x.plus ? 5 : 3); x.give(x.o, 194); } } });
