// cartas de raza: se suman a CARDS/NAMES y sus efectos especiales a FX
export const FX = {};
for (const [id, [nm, tx, c, sf, op, fx]] of Object.entries(RACE_CARDS)) { CARDS[id] = [c, sf, op]; NAMES[id] = [nm, tx]; if (fx) FX[id] = fx; }
for (const [id, [nm, tx, c, sf, op, fx]] of Object.entries(KING_CARDS)) { CARDS[id] = [c, sf, op]; NAMES[id] = [nm, tx]; if (fx) FX[id] = fx; }
for (const [id, [nm, tx, c, sf, op, fx]] of Object.entries(FAVOR_CARDS)) { CARDS[id] = [c, sf, op]; NAMES[id] = [nm, tx]; if (fx) FX[id] = fx; }
for (const [id, [nm, tx, c, sf, op, fx]] of Object.entries(TACTIC_CARDS)) { CARDS[id] = [c, sf, op]; NAMES[id] = [nm, tx]; if (fx) FX[id] = fx; }
for (const [id, [nm, tx, c, sf, op, fx]] of Object.entries(MYTHIC_CARDS)) { CARDS[id] = [c, sf, op]; NAMES[id] = [nm, tx]; if (fx) FX[id] = fx; } // míticas 180-185 (PvP)
for (const [id, [nm, tx, c, sf, op, fx]] of Object.entries(CAMPAIGN_CARDS)) { CARDS[id] = [c, sf, op]; NAMES[id] = [nm, tx]; if (fx) FX[id] = fx; } // solo campaña (190+), fuera de NCARDS
